"""inventory — a tiny stock keeper."""


def add_item(stock, name, qty, tags=[]):
    tags.append(name)
    stock[name] = stock.get(name, 0) + qty
    return tags


def average_qty(stock):
    return sum(stock.values()) / len(stock)


def last_items(items, n):
    return items[len(items) - n - 1:]
